using System.Text;
using System.Text.Json;

namespace MsfsUi.Core.Features;

/// <summary>
/// Writes <c>html_ui/msfs-ui/config.js</c>, the module the mod imports at start-up to read the user's settings
/// (ADR-0001).
/// </summary>
/// <remarks>
/// Format:
/// <code>
/// // Generated by MSFS-UI-GENERATOR 1.0.0. Do not edit: change the settings in MSFS-UI-GENERATOR.
/// export default {
///   "schemaVersion": 1,
///   "features": {
///     "weatherBar": { "enabled": true, "metar": true, … }
///   }
/// };
/// </code>
/// Strings are written with System.Text.Json's default encoder, which escapes every non-ASCII character
/// (including U+2028 and U+2029): the module is valid for Coherent GT, which predates ES2019.
/// </remarks>
public static class ConfigScript
{
    /// <summary>Schema version of the generated settings, read by the mod.</summary>
    public const int SchemaVersion = 1;

    /// <summary>The module text for a selection.</summary>
    public static string Generate(FeatureSelection selection, string generatorVersion)
    {
        ArgumentNullException.ThrowIfNull(selection);
        ArgumentNullException.ThrowIfNull(generatorVersion);

        using var buffer = new MemoryStream();
        using (var writer = new Utf8JsonWriter(buffer, new JsonWriterOptions { Indented = true, IndentSize = 2, NewLine = "\n" }))
        {
            writer.WriteStartObject();
            writer.WriteNumber("schemaVersion", SchemaVersion);
            writer.WriteStartObject("features");
            foreach (var feature in selection.Features)
            {
                writer.WriteStartObject(feature.Id);
                writer.WriteBoolean("enabled", feature.Enabled);
                foreach (var option in feature.Options)
                {
                    if (option.Value.Type == OptionType.Boolean)
                    {
                        writer.WriteBoolean(option.Id, option.Value.Boolean);
                    }
                    else
                    {
                        writer.WriteNumber(option.Id, option.Value.Number);
                    }
                }

                writer.WriteEndObject();
            }

            writer.WriteEndObject();
            writer.WriteEndObject();
        }

        var json = Encoding.UTF8.GetString(buffer.ToArray());
        return $"// Generated by {ProductInfo.Name} {generatorVersion}. Do not edit: change the settings in {ProductInfo.Name}.\nexport default {json};\n";
    }
}
